// ─── File: ComputeAdvisorDemo.java ───
// This file contains multiple classes for the runnable demo.
// In a real project each class would be in its own file.
package com.bank.compute;

import java.util.*;
import java.util.logging.*;

public class ComputeAdvisorDemo {
    private static final Logger log = Logger.getLogger("ComputeAdvisor");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ComputeAdvisor advisor = new ComputeAdvisor();

        List<Workload> workloads = List.of(
            new Workload("transfer-service", true,  false, false, false), // long-running container
            new Workload("statement-processor", false, true,  false, false), // bursty, event-driven
            new Workload("legacy-risk-engine", true, false, true,  false), // needs OS control
            new Workload("platform-portable",  true, false, false, true)); // needs Kubernetes

        for (Workload w : workloads) {
            log.info(() -> w.name() + " -> " + advisor.recommend(w));
        }
    }
}

// ─── Would be in ComputeAdvisor.java ───
class ComputeAdvisor {
    // Pick the least-operational option that fits the workload shape.
    String recommend(Workload w) {
        if (w.needsOsControl()) {
            return "EC2 (full VM control: custom OS/kernel tuning, licensed host software)";
        }
        if (w.bursty() && !w.longRunning()) {
            return "Lambda (serverless, event-driven, pay-per-ms, scales from zero)";
        }
        if (w.needsKubernetes()) {
            return "EKS (managed Kubernetes: portability + ecosystem, more complexity)";
        }
        return "ECS (AWS-native managed containers: simple, deep AWS integration)";
    }
}

// ─── Would be in Workload.java ───
class Workload {
    private final String name;
    private final boolean longRunning;
    private final boolean bursty;
    private final boolean needsOsControl;
    private final boolean needsKubernetes;
    Workload(String name, boolean longRunning, boolean bursty,
             boolean needsOsControl, boolean needsKubernetes) {
        this.name = name; this.longRunning = longRunning; this.bursty = bursty;
        this.needsOsControl = needsOsControl; this.needsKubernetes = needsKubernetes;
    }
    String name() { return name; }
    boolean longRunning() { return longRunning; }
    boolean bursty() { return bursty; }
    boolean needsOsControl() { return needsOsControl; }
    boolean needsKubernetes() { return needsKubernetes; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
